 $('saveGroup').addEventListener('click',()=>{if(busy)return;const ids=[...$('groupPersonas').querySelectorAll('input:checked')].map(el=>el.value);if(ids.length===1){$('groupStatus').textContent='Pilih minimal dua persona, atau kosongkan untuk mode tunggal.';return;}if(!currentChat())createChat();currentChat().groupPersonaIds=ids;persist();render();$('groupStatus').textContent=ids.length?'Peserta diskusi tersimpan.':'Mode tunggal aktif.';});
 $('chatAttachment').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;pendingAttachment=null;$('clearAttachment').hidden=true;try{const image=['image/jpeg','image/png','image/webp'].includes(file.type);const pdf=/\.pdf$/i.test(file.name);const docx=/\.docx$/i.test(file.name);const text=file.type==='text/plain'||/\.(txt|md)$/i.test(file.name);if(!image&&!pdf&&!docx&&!text)throw Error('Pilih gambar, PDF, DOCX, TXT, atau Markdown.');if(file.size>(image?512*1024:5*1024*1024))throw Error(image?'Gambar maksimal 512 KB.':'Dokumen maksimal 5 MB.');$('attachmentStatus').textContent='Membaca dokumen…';let data;if(image)data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Berkas tidak dapat dibaca.'));reader.readAsDataURL(file);});else if(pdf){const pdfjs=await import('./vendor/pdf.js');pdfjs.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.js';const document=await pdfjs.getDocument({data:await file.arrayBuffer(),isEvalSupported:false,enableXfa:false}).promise;try{if(document.numPages>100)throw Error('PDF maksimal 100 halaman.');let pages=[];for(let i=1;i<=document.numPages;i++){const page=await document.getPage(i);const content=await page.getTextContent();pages.push(content.items.map(x=>x.str||'').join(' '));if(pages.join('').length>100000)throw Error('Teks dokumen melebihi 100.000 karakter.');}data=pages.join('\n\n');}finally{await document.destroy();}}else if(docx){const zip=await JSZip.loadAsync(await file.arrayBuffer());const xml=zip.file('word/document.xml');if(!xml)throw Error('DOCX tidak memiliki isi dokumen.');if(xml._data?.uncompressedSize>3*1024*1024)throw Error('Isi dokumen terlalu besar.');const source=await xml.async('string');const document=new DOMParser().parseFromString(source,'application/xml');if(document.querySelector('parsererror'))throw Error('Dokumen DOCX tidak valid.');data=[...document.getElementsByTagNameNS('http://schemas.openxmlformats.org/wordprocessingml/2006/main','p')].map(p=>[...p.getElementsByTagNameNS('http://schemas.openxmlformats.org/wordprocessingml/2006/main','t')].map(t=>t.textContent).join('')).join('\n');}else data=await file.text();if(!image&&(!data.trim()||data.length>100000))throw Error(data.trim()?'Teks dokumen melebihi 100.000 karakter.':'Tidak ada teks yang dapat dibaca; PDF hasil pindai memerlukan OCR.');pendingAttachment={name:file.name.slice(0,150),type:image?'image':'text',data};$('attachmentStatus').textContent=file.name+(image?'':' · '+data.length+' karakter');$('clearAttachment').hidden=false;}catch(error){$('attachmentStatus').textContent=error.message;e.target.value='';}});
 $('clearAttachment').addEventListener('click',()=>{pendingAttachment=null;$('chatAttachment').value='';$('attachmentStatus').textContent='';$('clearAttachment').hidden=true;});
 $('replyPersona').addEventListener('change',()=>{const chosen=$('replyPersona').value;if(!currentChat())createChat();currentChat().replyPersonaId=chosen;persist();render();});
 $('searchCrossref').addEventListener('click',async()=>{const query=$('crossrefQuery').value.trim(),results=$('crossrefResults'),status=$('crossrefStatus');results.replaceChildren();if(!query){status.textContent='Masukkan kata kunci.';return;}status.textContent='Mencari publikasi…';try{const url=new URL('https://api.crossref.org/works');url.search=new URLSearchParams({query,rows:'5',select:'title,DOI,published,author'});const response=await fetch(url);if(!response.ok)throw Error('Layanan pencarian tidak tersedia.');const data=await response.json();const items=data.message?.items||[];status.textContent=items.length?'Pilih publikasi untuk menyimpan rujukan.':'Tidak ada hasil.';for(const item of items){if(!item.DOI||!item.title?.[0])continue;const row=document.createElement('div');row.className='saved-persona-item';const link=document.createElement('a');link.href='https://doi.org/'+encodeURIComponent(item.DOI);link.target='_blank';link.rel='noopener noreferrer';const year=item.published?.['date-parts']?.[0]?.[0];link.textContent=item.title[0]+(year?' ('+year+')':'');const button=document.createElement('button');button.className='save-preset-button';button.textContent='Tambah';button.type='button';button.onclick=()=>{const entry=link.href+' — '+link.textContent;const existing=$('sourcesInput').value.trim();if(!existing.includes(link.href))$('sourcesInput').value=(existing?existing+'\n':'')+entry;status.textContent='Rujukan ditambahkan. Simpan persona untuk menyimpannya.';};row.append(link,button);results.append(row);}}catch(error){status.textContent='Pencarian gagal: '+error.message;}});
 $('scenarioButton').addEventListener('click',()=>{if(busy)return;if(!currentChat())createChat();const chat=currentChat();const title=prompt('Nama skenario (kosongkan untuk menghapus):',chat.scenario?.title||'');if(title===null)return;if(!title.trim()){delete chat.scenario;persist();render();return;}const world=prompt('Lokasi, latar, dan situasi awal:',chat.scenario?.world||'');if(world===null)return;const rules=prompt('Aturan dunia dan arahan cerita:',chat.scenario?.rules||'');if(rules===null)return;chat.scenario={title:title.trim().slice(0,100),world:world.trim().slice(0,2000),rules:rules.trim().slice(0,2000)};persist();render();});
 $('deletePersonaChats').addEventListener('click',()=>{const count=chats.filter(c=>c.personaId===activePersonaId).length;if(!count){$('settingsStatus').textContent='Tidak ada riwayat untuk persona ini.';return;}if(!confirm('Hapus seluruh '+count+' percakapan persona ini secara permanen?'))return;chats=chats.filter(c=>c.personaId!==activePersonaId);currentId=null;persist();render();$('settingsStatus').textContent='Riwayat persona aktif telah dihapus.';});
 $('historySearch').addEventListener('input',renderSidebar);
 $('chatContent').addEventListener('click',async event=>{const button=event.target.closest('[data-msg-action]');if(!button||busy)return;const chat=currentChat();const i=Number(button.dataset.index);const message=chat?.messages[i];if(!message)return;const action=button.dataset.msgAction;if(action==='speak'){if(!window.speechSynthesis){alert('Browser ini belum mendukung pembacaan suara.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(message.text);utterance.lang='id-ID';speechSynthesis.speak(utterance);return;}if(action==='delete'){if(!confirm('Hapus pesan ini?'))return;chat.messages.splice(i,1);}if(action==='edit'){const text=prompt('Ubah pesan:',message.text);if(text===null||!text.trim())return;message.text=text.trim();message.intensity=detectIntensity(message.text);}if(action==='regenerate'){if(i!==chat.messages.length-1){alert('Buat ulang tersedia untuk balasan terakhir.');return;}const user=[...chat.messages.slice(0,i)].reverse().find(m=>m.role==='user');if(!user)return;button.disabled=true;try{const context={...chat,messages:chat.messages.slice(0,i)};const answer=persona.mode==='api'?await modelAnswer(context):demoAnswer(user.text);chat.messages[i]={role:'assistant',...answer,time:Date.now()};}catch(err){alert(`Gagal membuat ulang: ${err.message}`);button.disabled=false;return;}}persist();render();});
 for(const id of ['creativity','emotionSpeed'])$(id+'Input').addEventListener('input',e=>$(id+'Value').value=e.target.value+'%');
 $('exportPersona').addEventListener('click',()=>downloadJson('rasa-persona.json',{format:'rasa-ai-persona',version:1,persona:Object.fromEntries(profileKeys.map(k=>[k,readPersonaForm()[k]]))}));
 $('importPersona').addEventListener('change',async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(d.format!=='rasa-ai-persona'||!d.persona||typeof d.persona.name!=='string')throw Error('Berkas persona tidak valid.');const previous=persona;persona={...persona,...Object.fromEntries(profileKeys.filter(k=>d.persona[k]!==undefined).map(k=>[k,d.persona[k]]))};fillForm();persona=previous;$('personaTransferStatus').textContent='Persona diimpor ke formulir; periksa lalu simpan.';}catch(err){$('personaTransferStatus').textContent=err.message;}e.target.value='';});
 $('backupData').addEventListener('click',()=>downloadJson('rasa-cadangan.json',{format:'rasa-ai-backup',version:1,data:{persona,preferences,chats,currentId,savedPersonas,activePersonaId}}));
 $('restoreData').addEventListener('change',async e=>{try{const d=JSON.parse(await e.target.files[0].text());const v=d.data;if(d.format!=='rasa-ai-backup'||!v||!Array.isArray(v.chats)||!Array.isArray(v.savedPersonas)||!v.persona||!v.preferences)throw Error('Berkas cadangan tidak valid.');if(!confirm('Pulihkan cadangan? Data persona, pengaturan, dan percakapan saat ini akan diganti.'))return;localStorage.setItem(STORAGE,JSON.stringify(v));location.reload();}catch(err){$('backupStatus').textContent=err.message;}finally{e.target.value='';}});
 $('voiceInput').addEventListener('click',()=>{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){alert('Browser ini belum mendukung dikte suara.');return;}const recognition=new Recognition();recognition.lang='id-ID';recognition.onresult=e=>{const input=$('messageInput');input.value+=(input.value?' ':'')+e.results[0][0].transcript;resizeInput();updateDraftStatus();};recognition.onerror=()=>{$('draftStatus').textContent='Dikte tidak tersedia atau izin mikrofon ditolak.';};recognition.start();});
 $('searchCharacter').addEventListener('click',async()=>{const query=$('characterSearch').value.trim();const status=$('characterStatus');const results=$('characterResults');results.replaceChildren();if(!query){status.textContent='Masukkan nama tokoh terlebih dahulu.';return;}const lang=$('characterLanguage').value==='en'?'en':'id';status.textContent='Mencari sumber…';try{const url=new URL(`https://${lang}.wikipedia.org/w/api.php`);url.search=new URLSearchParams({action:'query',generator:'search',gsrsearch:query,gsrlimit:'5',prop:'extracts|info',exintro:'1',explaintext:'1',inprop:'url',format:'json',origin:'*'});const response=await fetch(url);if(!response.ok)throw new Error('Pencarian sumber gagal.');const data=await response.json();const pages=Object.values(data.query?.pages||{}).sort((a,b)=>a.index-b.index);if(!pages.length){status.textContent='Tidak ada hasil. Coba nama lain atau bahasa Inggris.';return;}status.textContent='Pilih artikel yang sesuai untuk dianalisis.';for(const page of pages){if(!page.extract)continue;const item=document.createElement('div');item.className='saved-persona-item';const info=document.createElement('div');info.className='saved-persona-info';const link=document.createElement('a');link.href=page.fullurl;link.target='_blank';link.rel='noopener noreferrer';link.textContent=page.title;const desc=document.createElement('span');desc.textContent=page.extract.slice(0,200)+'…';info.append(link,desc);const button=document.createElement('button');button.type='button';button.className='save-preset-button';button.textContent='Analisis';button.addEventListener('click',()=>analyzeCharacter(page,button));item.append(info,button);results.append(item);}}catch(error){status.textContent=`Pencarian gagal: ${error.message}`;}});
