 $('testApi').addEventListener('click',async()=>{const status=$('apiStatus');const button=$('testApi');const endpoint=$('endpointInput').value.trim();const key=$('apiKeyInput').value.trim();const model=$('modelInput').value.trim();if(!/^https:\/\//i.test(endpoint)||!key||!model){status.textContent='Isi endpoint HTTPS, nama model, dan kunci API.';return;}button.disabled=true;status.textContent='Menguji koneksi…';try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model,messages:[{role:'user',content:'Balas OK.'}],max_tokens:16})});if(!response.ok)throw new Error(`Penyedia menolak permintaan (${response.status}).`);const data=await response.json();if(!data.choices?.[0]?.message)throw new Error('Respons tidak kompatibel dengan Chat Completions.');status.textContent='Koneksi berhasil. Simpan perubahan untuk menggunakan model ini.';}catch(error){status.textContent=`Koneksi gagal: ${error.message}. Pastikan endpoint menerima akses dari browser (CORS).`;}finally{button.disabled=false;}});
